   466	export const searchFolios = internalQuery({
   467	  args: { userId: v.string(), search: v.string(), limit: v.number() },
   468	  returns: v.array(v.any()),
   469	  handler: async (ctx, { userId, search, limit }) => {
   470	    const needle = search.trim().toLowerCase();
   471	    if (!needle) return [];
   472	    const foliosRow = await ctx.db
   473	      .query("folios")
   474	      .withIndex("by_userId", (q) => q.eq("userId", userId))
   475	      .first();
   476	    const results: Array<Record<string, unknown>> = [];
   477	    for (const folio of (foliosRow?.folios ?? []).slice(
   478	      0,
   479	      MAX_FOLIOS_PER_ACCOUNT,
   480	    )) {
   481	      const content = await ctx.db
   482	        .query("folioContent")
   483	        .withIndex("by_userId_folioId", (q) =>
   484	          q.eq("userId", userId).eq("folioId", folio.id),
   485	        )
   486	        .first();
   487	      const text = (content?.html ?? "")
   488	        .replace(/<[^>]+>/g, " ")
   489	        .replace(/\s+/g, " ")
   490	        .trim();
   491	      const titleHit = String(folio.name ?? "")
   492	        .toLowerCase()
   493	        .includes(needle);
   494	      const bodyIndex = text.toLowerCase().indexOf(needle);
   495	      if (!titleHit && bodyIndex < 0) continue;
   496	      const start = Math.max(0, bodyIndex - 80);
   497	      results.push({
   498	        folio,
   499	        snippet: text.slice(start, start + needle.length + 240),
   500	        score: titleHit ? 2 : 1,
   501	      });
   502	    }
   503	    return results
   504	      .sort((a, b) => Number(b.score) - Number(a.score))
   505	      .slice(0, Math.max(1, Math.min(MAX_SEARCH_RESULTS, Math.floor(limit))));
   506	  },
   507	});
