   144	async function getRecord(
   145	  did: string,
   146	  collection: string,
   147	  rkey: string,
   148	  fetcher: Fetcher,
   149	  pds?: string,
   150	): Promise<UnknownRecord> {
   151	  const endpoint = pds ?? (await resolvePds(did, fetcher));
   152	  const url = new URL("/xrpc/com.atproto.repo.getRecord", endpoint);
   153	  url.searchParams.set("repo", did);
   154	  url.searchParams.set("collection", collection);
   155	  url.searchParams.set("rkey", rkey);
   156	  const envelope = recordObject(await fetchJson(url, fetcher));
   157	  const value = recordObject(envelope?.value);
   158	  if (!value) throw new Error("ATProto record is malformed");
   159	  return value;
