   208	function safeHref(value: string, image = false): string | null {
   209	  const trimmed = value.trim();
   210	  if (/^(?:\/|#|\.\/|\.\.\/)/.test(trimmed)) return trimmed;
   211	  try {
   212	    const url = new URL(trimmed);
   213	    if (url.protocol === "http:" || url.protocol === "https:") return trimmed;
   214	    if (!image && url.protocol === "mailto:") return trimmed;
   215	  } catch {
   216	    // Invalid and non-relative URLs are deliberately dropped.
   217	  }
   218	  return null;
   219	}
