   221	function escapeHtml(value: string): string {
   222	  return value
   223	    .replace(/&/g, "&amp;")
   224	    .replace(/</g, "&lt;")
   225	    .replace(/>/g, "&gt;")
   226	    .replace(/"/g, "&quot;")
   227	    .replace(/'/g, "&#39;");
   228	}
