   230	export function renderStandardSiteMarkdown(markdown: string): string {
   231	  const renderer = new Renderer();
   232	  renderer.html = ({ text }) => escapeHtml(text);
   233	  renderer.link = function ({ href, title, tokens }) {
   234	    const label = this.parser.parseInline(tokens);
   235	    const safe = safeHref(href);
   236	    if (!safe) return label;
   237	    const titleAttr = title ? ` title="${escapeHtml(title)}"` : "";
   238	    return `<a href="${escapeHtml(safe)}"${titleAttr} rel="nofollow ugc">${label}</a>`;
   239	  };
   240	  renderer.image = ({ href, title, text }) => {
   241	    const safe = safeHref(href, true);
   242	    if (!safe) return escapeHtml(text);
   243	    const titleAttr = title ? ` title="${escapeHtml(title)}"` : "";
   244	    return `<img src="${escapeHtml(safe)}" alt="${escapeHtml(text)}"${titleAttr}>`;
   245	  };
   246	  return marked.parse(markdown, {
   247	    async: false,
   248	    breaks: true,
   249	    gfm: true,
   250	    renderer,
   251	  }) as string;
   252	}
