    70	function safeServiceEndpoint(value: unknown): string | null {
    71	  if (typeof value !== "string") return null;
    72	  try {
    73	    const url = new URL(value);
    74	    const host = url.hostname.toLowerCase();
    75	    if (url.protocol !== "https:" || url.username || url.password) return null;
    76	    if (
    77	      host === "localhost" ||
    78	      host.endsWith(".localhost") ||
    79	      host.endsWith(".local") ||
    80	      host.endsWith(".internal") ||
    81	      /^\d{1,3}(?:\.\d{1,3}){3}$/.test(host) ||
    82	      host.startsWith("[")
    83	    ) {
    84	      return null;
    85	    }
    86	    return url.origin;
    87	  } catch {
    88	    return null;
    89	  }
