    92	async function fetchJson(
    93	  url: string | URL,
    94	  fetcher: Fetcher,
    95	): Promise<unknown> {
    96	  const controller = new AbortController();
    97	  const timeout = setTimeout(() => controller.abort(), REQUEST_TIMEOUT_MS);
    98	  try {
    99	    const response = await fetcher(url, {
   100	      headers: { Accept: "application/json" },
   101	      redirect: "error",
   102	      signal: controller.signal,
   103	    });
   104	    if (!response.ok)
   105	      throw new Error(`ATProto request failed (${response.status})`);
   106	    const declaredSize = Number(response.headers.get("content-length") ?? 0);
   107	    if (declaredSize > MAX_RECORD_BYTES)
   108	      throw new Error("ATProto record is too large");
   109	    const text = await response.text();
   110	    if (text.length > MAX_RECORD_BYTES)
   111	      throw new Error("ATProto record is too large");
   112	    return JSON.parse(text) as unknown;
   113	  } finally {
   114	    clearTimeout(timeout);
   115	  }
   116	}
