   118	async function resolvePds(did: string, fetcher: Fetcher): Promise<string> {
   119	  // PLC identities cover Bluesky and self-hosted PDS users while keeping DID
   120	  // resolution on one trusted origin. did:web support would require a fully
   121	  // DNS-aware SSRF defence before it is safe to add to a server-side reader.
   122	  if (!PLC_DID_RE.test(did)) throw new Error("Unsupported ATProto DID");
   123	  const document = recordObject(
   124	    await fetchJson(
   125	      `https://plc.directory/${encodeURIComponent(did)}`,
   126	      fetcher,
   127	    ),
   128	  );
   129	  const services = Array.isArray(document?.service) ? document.service : [];
   130	  for (const candidate of services) {
   131	    const service = recordObject(candidate);
   132	    if (
   133	      service?.type !== "AtprotoPersonalDataServer" &&
   134	      service?.id !== "#atproto_pds"
   135	    ) {
   136	      continue;
   137	    }
   138	    const endpoint = safeServiceEndpoint(service?.serviceEndpoint);
   139	    if (endpoint) return endpoint;
   140	  }
   141	  throw new Error("ATProto PDS service is unavailable");
   142	}
