   162	async function listDocumentRecords(
   163	  did: string,
   164	  fetcher: Fetcher,
   165	  pds: string,
   166	): Promise<Array<{ uri: string; value: UnknownRecord }>> {
   167	  const url = new URL("/xrpc/com.atproto.repo.listRecords", pds);
   168	  url.searchParams.set("repo", did);
   169	  url.searchParams.set("collection", STANDARD_SITE_DOCUMENT_COLLECTION);
   170	  url.searchParams.set("limit", "100");
   171	  url.searchParams.set("reverse", "true");
   172	  const envelope = recordObject(await fetchJson(url, fetcher));
   173	  const records = Array.isArray(envelope?.records) ? envelope.records : [];
   174	  return records.flatMap((candidate) => {
   175	    const entry = recordObject(candidate);
   176	    const uri = typeof entry?.uri === "string" ? entry.uri : null;
   177	    const value = recordObject(entry?.value);
   178	    return uri && value ? [{ uri, value }] : [];
   179	  });
   180	}
