 66	export function parseArchive(input: string | unknown): TwyneArchiveV2 {
 67	  let parsed: unknown = input;
 68	  if (typeof input === "string") {
 69	    try {
 70	      parsed = JSON.parse(input);
 71	    } catch (error) {
 72	      throw new Error(
 73	        `Twyne archive is not valid JSON: ${error instanceof Error ? error.message : String(error)}`,
 74	      );
 75	    }
 76	  }
 77	  if (!isRecord(parsed)) throw new Error("Twyne archive must be a JSON object");
 78	  if (parsed.format !== TWYNE_ARCHIVE_FORMAT || parsed.version !== TWYNE_ARCHIVE_VERSION) {
 79	    throw new Error(
 80	      `Expected a ${TWYNE_ARCHIVE_FORMAT} version ${TWYNE_ARCHIVE_VERSION} bundle`,
 81	    );
 82	  }
 83	  if (!Array.isArray(parsed.folios)) throw new Error("Twyne archive folios must be an array");
 84	  const folios = parsed.folios.map((entry, index): FolioBundle => {
 85	    if (!isRecord(entry)) throw new Error(`Archive folio ${index + 1} must be an object`);
 86	    const folio = requireFolio(entry.folio, index);
 87	    if (entry.html !== undefined && typeof entry.html !== "string") {
 88	      throw new Error(`Archive folio ${index + 1} has invalid html`);
 89	    }
 90	    if (entry.citations !== undefined && !Array.isArray(entry.citations)) {
 91	      throw new Error(`Archive folio ${index + 1} has invalid citations`);
 92	    }
 93	    return { ...entry, folio } as FolioBundle;
 94	  });
 95	  return {
 96	    format: TWYNE_ARCHIVE_FORMAT,
 97	    version: TWYNE_ARCHIVE_VERSION,
 98	    exportedAt: typeof parsed.exportedAt === "string" ? parsed.exportedAt : new Date(0).toISOString(),
 99	    folios,
100	  };
101	}
