139	async function readAccessToken(io: CliIo): Promise<string> {
140	  if (!process.stdin.isTTY || typeof process.stdin.setRawMode !== "function") {
141	    return await readStdin();
142	  }
143	  const input = process.stdin;
144	  const wasRaw = input.isRaw;
145	  io.stdout.write("Twyne access token: ");
146	  return await new Promise<string>((resolve, reject) => {
147	    let value = "";
148	    const cleanup = () => {
149	      input.off("data", onData);
150	      input.setRawMode(wasRaw);
151	      input.pause();
152	      io.stdout.write("\n");
153	    };
154	    const onData = (chunk: Buffer | string) => {
155	      for (const character of String(chunk)) {
156	        if (character === "\u0003") {
157	          cleanup();
158	          reject(new Error("Login cancelled"));
159	          return;
160	        }
161	        if (character === "\r" || character === "\n") {
162	          cleanup();
163	          resolve(value.trim());
164	          return;
165	        }
166	        if (character === "\u007f" || character === "\b") {
167	          value = value.slice(0, -1);
168	        } else if (character >= " ") {
169	          value += character;
170	        }
171	      }
172	    };
173	    input.setRawMode(true);
174	    input.resume();
175	    input.on("data", onData);
176	  });
177	}
